 import unittest
from unittest.mock import Mock
from candidate import has_close_elements

class TestHasCloseElements(unittest.TestCase):
    def test_normalcase(self):
        self.assertTrue(has_close_elements([1.0, 2.8, 3.0, 4.0, 5.0, 2.0], 0.3))

    def test_empty_list(self):
        self.assertFalse(has_close_elements([] , 0.3))

    def test_single_element(self):
        self.assertFalse(has_close_elements([1.0], 0.3))

    def test_threshold_equal_to_distance(self):
        self.assertTrue(has_close_elements([1.0, 1.3], 0.3))

    def test_threshold_larger_than_distance(self):
        self.assertFalse(has_close_elements([1.0, 1.3], 1.0))

    def test_negative_numbers(self):
        self.assertTrue(has_close_elements([-1.0, -2.8, -3.0, -4.0, -5.0, -2.0], 0.3))

    def test_mixed_numbers(self):
        self.assertTrue(has_close_elements([1.0, -2.8, 3.0, 4.0, 5.0, 2.0], 0.7))

    def test_float_threshold(self):
        self.assertTrue(has_close_elements([1.0, 2.8, 3.0, 4.0, 5.0, 2.0], 0.4))

    def test_none_threshold(self):
        with self.assertRaises(TypeError):
            has_close_elements([1.0, 2.8, 3.0, 4.0, 5.0, 2.0], None)

    def test_list_of_strings(self):
        numbers = ["1.0", "2.8", "3.0", "4.0", "5.0", "2.0"]
        with self.assertRaises(TypeError):
            has_close_elements(numbers, 0.3)

if __name__ == '__main__':
    unittest.main()
